using NUnit.Framework;
using UnityEditor;
using UnityEngine;
using UnityEngine.Rendering;
using UnityEngine.Rendering.Universal;

namespace Crashverse.Rendering.Tests
{
    public class LightingPostTests
    {
        // Clean CI checkout: URP tier assets are generated by UrpSetup + LightingSetup (editor load + every build). Run them first.
        [OneTimeSetUp]
        public void EnsureUrp()
        {
            var t = System.Type.GetType("Crashverse.EditorTools.LightingSetup, Assembly-CSharp-Editor");
            Assert.IsNotNull(t, "LightingSetup editor script missing");
            t.GetMethod("Ensure").Invoke(null, null);
        }

        [Test]
        public void UrpTierAssets_MatchRenderTiers()
        {
            foreach (var t in RenderTiers.All)
            {
                var a = AssetDatabase.LoadAssetAtPath<UniversalRenderPipelineAsset>($"Assets/_Project/Settings/URP/URP_{t.name}.asset");
                Assert.NotNull(a, $"URP_{t.name} missing (UrpSetup, PR #23)");
                Assert.AreEqual(t.hdr, a.supportsHDR, t.name + " HDR");
                Assert.AreEqual(t.msaa, a.msaaSampleCount, t.name + " MSAA");
                Assert.AreEqual(t.renderScale, a.renderScale, 1e-3f, t.name + " renderScale");
                Assert.AreEqual(t.shadowDistance, a.shadowDistance, 1e-3f, t.name + " shadowDistance");
                Assert.AreEqual(t.cascades, a.shadowCascadeCount, t.name + " cascades");
                Assert.AreEqual(t.mainShadows, a.supportsMainLightShadows, t.name + " main shadows");
                Assert.AreEqual(t.srpBatcher, a.useSRPBatcher, t.name + " SRP batcher");
                Assert.AreEqual(t.additionalLights, a.maxAdditionalLightsCount, t.name + " additional lights");
            }
        }

        [Test]
        public void LowTier_IsCheapest()
        {
            var low = RenderTiers.All[0];
            Assert.IsFalse(low.hdr || low.bloom || low.vignette || low.mainShadows || low.additionalLights > 0);
            Assert.AreEqual(1, low.msaa);
        }

        [Test]
        public void VolumeProfiles_HaveExpectedEffects()
        {
            var full = Resources.Load<VolumeProfile>(RenderTiers.VolumeFullResource);
            var low = Resources.Load<VolumeProfile>(RenderTiers.VolumeLowResource);
            Assert.NotNull(full, "VP_Global missing"); Assert.NotNull(low, "VP_Global_Low missing");
            Assert.IsTrue(full.Has<Bloom>() && full.Has<Tonemapping>() && full.Has<ColorAdjustments>() && full.Has<Vignette>());
            Assert.IsTrue(low.Has<Tonemapping>() && low.Has<ColorAdjustments>());
            Assert.IsFalse(low.Has<Bloom>() || low.Has<Vignette>(), "Low must skip Bloom/Vignette");
            Assert.IsFalse(full.Has<DepthOfField>() || full.Has<MotionBlur>(), "no expensive effects");
        }

        [Test]
        public void Tonemapping_IsAcesOnEveryTier_WithWarmGrade()
        {
            foreach (var res in new[] { RenderTiers.VolumeFullResource, RenderTiers.VolumeLowResource })
            {
                var p = Resources.Load<VolumeProfile>(res);
                Assert.NotNull(p, res);
                Assert.IsTrue(p.TryGet<Tonemapping>(out var tm) && tm.active, res + ": Tonemapping");
                Assert.AreEqual(TonemappingMode.ACES, tm.mode.value, res + ": user decision 2026-10-31: ACES on every tier");
                Assert.IsTrue(p.TryGet<ColorAdjustments>(out var ca));
                Assert.AreEqual(RenderTiers.PostExposure, ca.postExposure.value, 1e-4f, res + " exposure");
                Assert.AreEqual(RenderTiers.PostContrast, ca.contrast.value, 1e-4f, res + " contrast");
                Assert.AreEqual(RenderTiers.PostSaturation, ca.saturation.value, 1e-4f, res + " saturation");
                Assert.IsTrue(p.TryGet<WhiteBalance>(out var wb) && wb.temperature.value > 0f, res + ": warm white balance");
                Assert.IsTrue(p.TryGet<SplitToning>(out _), res + ": split toning");
            }
            var full = Resources.Load<VolumeProfile>(RenderTiers.VolumeFullResource);
            Assert.IsTrue(full.TryGet<Bloom>(out var b));
            Assert.GreaterOrEqual(b.threshold.value, 0.9f, "bloom only on bright highlights");
            Assert.LessOrEqual(b.intensity.value, 1f, "moderate bloom");
            Assert.IsTrue(full.TryGet<Vignette>(out var v)); Assert.LessOrEqual(v.intensity.value, 0.3f, "framing vignette");
            foreach (var t in RenderTiers.All) if (t.bloom) Assert.IsTrue(t.hdr, t.name + ": HDR bloom threshold needs an HDR tier");
        }

        [Test]
        public void SunAndSky_FollowStyleBoardV3()
        {
            Assert.AreEqual((Color32)RenderTiers.SunColor, new Color32(0xFF, 0xF4, 0xE0, 0xFF), "sun #FFF4E0");
            Assert.That(RenderTiers.SunEuler.x, Is.InRange(55f, 60f), "sun elevation 55-60°");
            var m = Resources.Load<Material>(RenderTiers.SkyboxResource);
            Assert.AreEqual((Color32)RenderTiers.SkyTop, (Color32)m.GetColor("_SkyTint"), "sky #4FB8FF");
            Assert.AreEqual((Color32)RenderTiers.SkyHorizon, (Color32)m.GetColor("_GroundColor"), "horizon #FFE3A3");
        }

        [Test]
        public void Skybox_ShipsInResources()
        {
            var m = Resources.Load<Material>(RenderTiers.SkyboxResource);
            Assert.NotNull(m); Assert.AreEqual("Skybox/Procedural", m.shader.name);
        }

        [Test]
        public void TierLookup_MapsQualityNames()
        {
            Assert.AreEqual(0, RenderTiers.IndexFor("Low")); Assert.AreEqual(1, RenderTiers.IndexFor("Mid")); Assert.AreEqual(2, RenderTiers.IndexFor("High"));
        }
    }
}
